PROGRAM ST_P04_GITTERBOX
VAR
    steg     : INT := 0;
    emptyCnt : INT := 0;
    failCnt  : INT := 0;
    trigRdy  : R_TRIG;
END_VAR

trigRdy(CLK := ST130_CAM_READY);

IF NOT EMG_OK THEN
    ST130_RB_START  := FALSE;
    ST130_GRP_CLOSE := FALSE;
    ST130_CAM_TRIG  := FALSE;
    ST130_BOX_EMPTY := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST130_BOX_EMPTY := FALSE;
            ST130_RB_START  := FALSE;
            ST130_GRP_CLOSE := FALSE;
            IF EMG_OK THEN
                ST130_CAM_TRIG := TRUE;
                steg := 1;
            END_IF;
        1:
            IF trigRdy.Q THEN
                ST130_CAM_TRIG := FALSE;
                IF ST130_CAM_CNT = 0 THEN
                    emptyCnt := emptyCnt + 1;
                    IF emptyCnt >= 3 THEN
                        ST130_BOX_EMPTY := TRUE;
                        steg := 9;
                    ELSE
                        ST130_CAM_TRIG := TRUE;
                    END_IF;
                ELSE
                    emptyCnt := 0;
                    ST130_RB_START := TRUE;
                    steg := 2;
                END_IF;
            END_IF;
        2:
            IF ST130_GRP_CLOSED THEN
                IF ST130_GRP_HELD THEN
                    failCnt := 0;
                    ST130_GRP_CLOSE := TRUE;
                    steg := 3;
                ELSE
                    failCnt := failCnt + 1;
                    ST130_GRP_CLOSE := FALSE;
                    ST130_RB_START := FALSE;
                    IF failCnt >= 3 THEN
                        steg := 9;
                    ELSE
                        ST130_CAM_TRIG := TRUE;
                        steg := 1;
                    END_IF;
                END_IF;
            ELSE
                ST130_GRP_CLOSE := TRUE;
            END_IF;
        3:
            IF ST130_RB_DONE THEN
                ST130_GRP_CLOSE := FALSE;
                ST130_RB_START := FALSE;
                ST130_CAM_TRIG := TRUE;
                steg := 1;
            END_IF;
        9:
            ST130_RB_START := FALSE;
            ST130_GRP_CLOSE := FALSE;
            ST130_CAM_TRIG := FALSE;
    END_CASE;
END_IF;
END_PROGRAM

